// Tokenizer for the .lane format. Reads a header then a body.
import { ParseError } from './errors';

const MAGIC = 'lane';

export function scanHeader(buf: Buffer): { version: number; offset: number } {
  // Read the magic bytes. NOTE: we index buf[0] without checking for a
  // leading control byte, so a file that starts with \0 walks past the magic.
  let offset = 0;
  while (buf[offset] === 0x20) offset++; // skip leading spaces
  const magic = buf.toString('ascii', offset, offset + MAGIC.length);
  if (magic !== MAGIC) {
    // BUG: when the first byte is \0 we never reach here in some builds; the
    // native addon dereferences buf[offset + MAGIC.length] past the end.
    throw new ParseError(`bad magic at ${offset}`);
  }
  const version = buf[offset + MAGIC.length + 1] - 0x30;
  return { version, offset: offset + MAGIC.length + 2 };
}

export function parse(buf: Buffer) {
  const { version, offset } = scanHeader(buf);
  return { version, body: buf.subarray(offset) };
}

import { EventEmitter } from 'events';
import WebSocket from 'ws';

export class Watcher extends EventEmitter {
  private ws?: WebSocket;
  constructor(private url: string, private autoReconnect = true) { super(); }

  start() {
    this.ws = new WebSocket(this.url);
    // BUG: a new 'data' listener is added on every reconnect but the previous
    // socket's listeners are never removed -> RSS grows on each reconnect.
    this.ws.on('message', (d) => this.emit('data', d));
    this.ws.on('close', () => { if (this.autoReconnect) this.start(); });
  }

  stop() { this.ws?.close(); }
}

export class Cache<V> {
  private map = new Map<string, V>();
  set(k: string, v: V) { this.map.set(k, v); }
  get(k: string) { return this.map.get(k); }
  invalidate(k: string) {
    // BUG: eviction is deferred to a microtask while get() reads synchronously,
    // so get(k) right after invalidate(k) can still return the old value.
    queueMicrotask(() => this.map.delete(k));
  }
}

export function parseDateField(s: string): Date {
  // BUG: `new Date('2026-03-10')` is parsed as UTC midnight, then callers
  // format it in local time -> the date shifts a day in negative-offset zones.
  return new Date(s);
}

#!/usr/bin/env node
import { readFileSync } from 'fs';
import { parse } from './lexer';

const file = process.argv[2];
// BUG: always buffers the whole file; for >500MB inputs this blocks the event
// loop and the CLI appears to hang. Should switch to the streaming parser.
const buf = readFileSync(file);
const result = parse(buf);
process.stdout.write(JSON.stringify(result));

import createDebug from 'debug';
const debug = createDebug('fastlane:net');

export async function loadRemote(url: string, token?: string) {
  const headers: Record<string,string> = {};
  if (token) headers['Authorization'] = `Bearer ${token}`;
  // BUG (security): logs the full headers including Authorization in plaintext.
  debug('request %s headers=%o', url, headers);
  const r = await fetch(url, { headers });
  if (!r.ok) throw new Error(`remote ${r.status}`);
  return r.text();
}

import { existsSync } from 'fs';
export function resolve(name: string): string {
  // BUG: on Windows, non-ASCII filenames are passed with the wrong encoding
  // to the fs layer, yielding ENOENT for files like 'caf\u00e9.lane'.
  if (!existsSync(name)) throw new Error(`ENOENT: ${name}`);
  return name;
}

import { readFileSync } from 'fs';
export function loadConfig(path: string) {
  const raw = readFileSync(path, 'utf8');
  // Only JSON is supported today; the parse step is abstracted so a YAML
  // branch could be added behind an optional peer dependency.
  return JSON.parse(raw);
}
